searchToggle.addEventListener('click', () => {
    searchBar.classList.toggle('hidden');
    if (!searchBar.classList.contains('hidden')) {
        searchInput.focus();
    }
});

searchInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
        const query = searchInput.value.trim();
        if (query) {
            console.log('Searching for:', query);
            searchBar.classList.add('hidden');
            searchInput.value = '';
        }
    }
});

document.addEventListener('click', (e) => {
    if (!e.target.closest('.search-toggle') && 
        !e.target.closest('.search-bar') && 
        !searchBar.classList.contains('hidden')) {
        searchBar.classList.add('hidden');
    }
});

/* ============================================================================
   Cart Functionality
   ============================================================================ */

cartToggle.addEventListener('click', () => {
    cartSidebar.classList.toggle('hidden');
    overlay.classList.toggle('hidden');
});

closeBtn.addEventListener('click', () => {
    cartSidebar.classList.add('hidden');
    overlay.classList.add('hidden');
});

overlay.addEventListener('click', () => {
    cartSidebar.classList.add('hidden');
    overlay.classList.add('hidden');
});

function addToCart(product) {
    const existingItem = cart.find(item => item.name === product.name);

    if (existingItem) {
        existingItem.quantity++;
    } else {
        cart.push({
            ...product,
            quantity: 1
        });
    }

    updateCartCount();
    showCartNotification();
}

function updateCartCount() {
    const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);
    cartCount.textContent = totalItems;
}

function showCartNotification() {
    const lastItem = cart[cart.length - 1];
    console.log(`${lastItem.name} added to cart`);
}

addToCartButtons.forEach((button, index) => {
    button.addEventListener('click', (e) => {
        e.stopPropagation();

        const productCard = button.closest('.product-card');
        const productName = productCard.querySelector('h3').textContent;
        const productPrice = parseFloat(productCard.querySelector('.price').textContent.replace('$', ''));

        addToCart({
            id: index,
            name: productName,
            price: productPrice
        });

        button.textContent = '✓';
        setTimeout(() => {
            button.innerHTML = '<span>+</span>';
        }, 1500);
    });
});

/* ============================================================================
   Newsletter Subscription
   ============================================================================ */

newsletterForm.addEventListener('submit', (e) => {
    e.preventDefault();

    const email = newsletterForm.querySelector('input[type="email"]').value;
    console.log('Newsletter signup:', email);

    const button = newsletterForm.querySelector('button');
    const originalText = button.textContent;
    button.textContent = 'Subscribed!';
    button.style.backgroundColor = '#10b981';

    setTimeout(() => {
        button.textContent = originalText;
        button.style.backgroundColor = '';
        newsletterForm.reset();
    }, 2500);
});

/* ============================================================================
   Smooth Scroll & Interactions
   ============================================================================ */

document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
        const href = this.getAttribute('href');
        if (href !== '#') {
            e.preventDefault();
            const target = document.querySelector(href);
            if (target) {
                target.scrollIntoView({ behavior: 'smooth' });
            }
        }
    });
});

const buttons = document.querySelectorAll('.btn');
buttons.forEach(button => {
    button.addEventListener('click', function() {
        if (this.textContent.includes('Explore')) {
            console.log('Exploring featured products');
        } else if (this.textContent.includes('Shop')) {
            console.log('Shopping deals');
        }
    });
});

/* ============================================================================
   Lazy Load Animations
   ============================================================================ */

const observerOptions = {
    threshold: 0.1,
    rootMargin: '0px 0px -50px 0px'
};

const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            entry.target.style.opacity = '1';
            entry.target.style.transform = 'translateY(0)';
        }
    });
}, observerOptions);

document.querySelectorAll('.product-card, .deal-card, .editorial-card').forEach(card => {
    card.style.opacity = '0';
    card.style.transform = 'translateY(20px)';
    card.style.transition = 'opacity 600ms ease-in-out, transform 600ms ease-in-out';
    observer.observe(card);
});

/* ============================================================================
   Product Card Hover Effect
   ============================================================================ */

document.querySelectorAll('.product-card').forEach(card => {
    card.addEventListener('mouseenter', function() {
        this.style.filter = 'brightness(1.1)';
    });

    card.addEventListener('mouseleave', function() {
        this.style.filter = 'brightness(1)';
    });
});

/* ============================================================================
   Responsive Navigation
   ============================================================================ */

window.addEventListener('resize', () => {
    if (window.innerWidth > 768) {
        searchBar.classList.add('hidden');
    }
});

/* ============================================================================
   Keyboard Navigation
   ============================================================================ */

document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
        searchBar.classList.add('hidden');
        cartSidebar.classList.add('hidden');
        overlay.classList.add('hidden');
    }
});

/* ============================================================================
   Performance: Debounce for scroll events
   ============================================================================ */

function debounce(func, delay) {
    let timeoutId;
    return function(...args) {
        clearTimeout(timeoutId);
        timeoutId = setTimeout(() => func(...args), delay);
    };
}

const handleScroll = debounce(() => {
    const header = document.querySelector('.header');
    if (window.scrollY > 50) {
        header.style.boxShadow = '0 10px 25px rgba(0, 0, 0, 0.3)';
    } else {
        header.style.boxShadow = 'none';
    }
}, 100);

window.addEventListener('scroll', handleScroll);

/* ============================================================================
   Initialize
   ============================================================================ */

console.log('✓ Luxe & Co. ecommerce site loaded successfully');
