/* ============================================================================
   Root & Layout Variables
   ============================================================================ */

:root {
    --color-bg-primary: #0a0e27;
    --color-bg-secondary: #12152e;
    --color-bg-tertiary: #1a1f3a;
    --color-text-primary: #ffffff;
    --color-text-secondary: #b8b8cc;
    --color-text-muted: #777788;
    --color-accent: #d4af37;
    --color-accent-hover: #e5c158;
    --color-accent-alt: #7c4fd9;
    --color-accent-alt-hover: #8f5ff0;
    --color-border: #2a2f48;
    --color-success: #10b981;
    --color-error: #ef4444;

    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 1.5rem;
    --spacing-lg: 2rem;
    --spacing-xl: 3rem;
    --spacing-2xl: 4rem;

    --radius-sm: 0.375rem;
    --radius-md: 0.5rem;
    --radius-lg: 1rem;

    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.3);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.4);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.5);
    --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.6);

    --transition-fast: 150ms ease-in-out;
    --transition-base: 300ms ease-in-out;
    --transition-slow: 500ms ease-in-out;
}

/* ============================================================================
   Global Styles
   ============================================================================ */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
        'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
        sans-serif;
    background-color: var(--color-bg-primary);
    color: var(--color-text-primary);
    line-height: 1.6;
    overflow-x: hidden;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
}

/* ============================================================================
   Typography
   ============================================================================ */

h1, h2, h3, h4, h5, h6 {
    font-weight: 600;
    line-height: 1.2;
    letter-spacing: -0.02em;
}

h1 {
    font-size: 2.5rem;
}

h2 {
    font-size: 2rem;
}

h3 {
    font-size: 1.5rem;
}

h4 {
    font-size: 1.25rem;
}

p {
    color: var(--color-text-secondary);
}

a {
    color: inherit;
    text-decoration: none;
    transition: color var(--transition-fast);
}

/* ============================================================================
   Buttons
   ============================================================================ */

.btn {
    display: inline-block;
    padding: 0.75rem 1.5rem;
    border: none;
    border-radius: var(--radius-md);
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
    transition: all var(--transition-base);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.btn-primary {
    background-color: var(--color-accent);
    color: var(--color-bg-primary);
}

.btn-primary:hover {
    background-color: var(--color-accent-hover);
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
}

.btn-secondary {
    background-color: var(--color-accent-alt);
    color: var(--color-text-primary);
}

.btn-secondary:hover {
    background-color: var(--color-accent-alt-hover);
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
}

.btn-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2.5rem;
    height: 2.5rem;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    background-color: var(--color-bg-secondary);
    color: var(--color-text-primary);
    font-size: 1.25rem;
    cursor: pointer;
    transition: all var(--transition-fast);
}

.btn-icon:hover {
    border-color: var(--color-accent);
    color: var(--color-accent);
    background-color: rgba(212, 175, 55, 0.1);
}

/* ============================================================================
   Header
   ============================================================================ */

.header {
    position: sticky;
    top: 0;
    z-index: 100;
    background-color: var(--color-bg-primary);
    border-bottom: 1px solid var(--color-border);
}

.header-top {
    padding: var(--spacing-md) 0;
}

.header-content {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-xl);
}

.logo h1 {
    letter-spacing: 0.15em;
    color: var(--color-accent);
    font-size: 1.5rem;
}

.nav-main {
    display: flex;
    gap: var(--spacing-xl);
    flex: 1;
}

.nav-link {
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-text-secondary);
    position: relative;
    padding-bottom: 0.25rem;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--color-accent);
    transition: width var(--transition-fast);
}

.nav-link:hover::after {
    width: 100%;
}

.header-actions {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
}

.search-toggle,
.cart-toggle {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.25rem;
    color: var(--color-text-primary);
    transition: color var(--transition-fast);
    position: relative;
}

.search-toggle:hover,
.cart-toggle:hover {
    color: var(--color-accent);
}

.cart-count {
    position: absolute;
    top: -0.5rem;
    right: -0.5rem;
    background-color: var(--color-accent);
    color: var(--color-bg-primary);
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    font-weight: 700;
}

.search-bar {
    border-top: 1px solid var(--color-border);
    padding: var(--spacing-md) 0;
    background-color: var(--color-bg-secondary);
    transition: all var(--transition-fast);
}

.search-bar.hidden {
    display: none;
}

.search-input {
    width: 100%;
    padding: 0.75rem;
    background-color: var(--color-bg-tertiary);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    color: var(--color-text-primary);
    font-size: 1rem;
}

.search-input::placeholder {
    color: var(--color-text-muted);
}

.search-input:focus {
    outline: none;
    border-color: var(--color-accent);
    box-shadow: 0 0 0 3px rgba(212, 175, 55, 0.1);
}

/* ============================================================================
   Hero Section
   ============================================================================ */

.hero {
    padding: var(--spacing-2xl) var(--spacing-lg);
    background: linear-gradient(135deg, var(--color-bg-secondary) 0%, var(--color-bg-tertiary) 100%);
    border-bottom: 1px solid var(--color-border);
    text-align: center;
}

.hero-content {
    max-width: 600px;
    margin: 0 auto;
}

.hero-content h2 {
    margin-bottom: var(--spacing-md);
    background: linear-gradient(90deg, var(--color-accent), var(--color-accent-alt));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    font-size: 3rem;
}

.hero-content p {
    font-size: 1.125rem;
    margin-bottom: var(--spacing-lg);
    color: var(--color-text-secondary);
}

/* ============================================================================
   Sections
   ============================================================================ */

section {
    padding: var(--spacing-2xl) 0;
    border-bottom: 1px solid var(--color-border);
}

.section-header {
    text-align: center;
    margin-bottom: var(--spacing-2xl);
}

.section-header h2 {
    margin-bottom: var(--spacing-sm);
    color: var(--color-text-primary);
}

.section-subtitle {
    font-size: 1.125rem;
    color: var(--color-text-secondary);
}

/* ============================================================================
   Featured Products
   ============================================================================ */

.featured {
    background-color: var(--color-bg-primary);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-xl);
}

.product-card {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: all var(--transition-base);
    cursor: pointer;
}

.product-card:hover {
    border-color: var(--color-accent);
    transform: translateY(-8px);
    box-shadow: 0 20px 25px -5px rgba(212, 175, 55, 0.2);
}

.product-image {
    position: relative;
    width: 100%;
    aspect-ratio: 1;
    background-color: var(--color-bg-tertiary);
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.image-placeholder {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, var(--color-bg-tertiary), var(--color-accent-alt));
    opacity: 0.3;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--color-text-muted);
    font-weight: 600;
}

.image-placeholder.large {
    aspect-ratio: 16 / 9;
}

.badge {
    position: absolute;
    top: var(--spacing-sm);
    right: var(--spacing-sm);
    background-color: var(--color-accent);
    color: var(--color-bg-primary);
    padding: 0.375rem 0.75rem;
    border-radius: var(--radius-sm);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.product-info {
    padding: var(--spacing-md);
}

.product-info h3 {
    margin-bottom: var(--spacing-xs);
    font-size: 1.125rem;
}

.product-category {
    font-size: 0.875rem;
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-sm);
}

.product-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: var(--spacing-md);
}

.price {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--color-accent);
}

/* ============================================================================
   Deals Section
   ============================================================================ */

.deals {
    background-color: var(--color-bg-secondary);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-lg);
}

.deal-card {
    background: linear-gradient(135deg, var(--color-bg-tertiary), var(--color-accent-alt));
    border: 1px solid var(--color-accent-alt);
    border-radius: var(--radius-lg);
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    transition: all var(--transition-base);
    min-height: 280px;
}

.deal-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-xl);
    border-color: var(--color-accent);
}

.deal-large {
    grid-column: span 2;
    background: linear-gradient(135deg, var(--color-accent-alt), var(--color-accent));
    min-height: auto;
}

.deal-content {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

.deal-label {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    color: var(--color-bg-primary);
    opacity: 0.9;
}

.deal-card h3 {
    font-size: 1.5rem;
    color: var(--color-text-primary);
}

.deal-large h3 {
    color: var(--color-bg-primary);
}

.deal-discount {
    font-size: 2rem;
    font-weight: 700;
    color: var(--color-text-primary);
}

.deal-large .deal-discount {
    color: var(--color-bg-primary);
}

.deal-terms {
    font-size: 0.875rem;
    color: var(--color-text-secondary);
}

.deal-large .deal-terms {
    color: rgba(10, 14, 39, 0.8);
}

/* ============================================================================
   Editorial Section
   ============================================================================ */

.editorial {
    background-color: var(--color-bg-primary);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-xl);
}

.editorial-card {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: all var(--transition-base);
}

.editorial-card:hover {
    border-color: var(--color-accent);
    transform: translateY(-4px);
    box-shadow: 0 15px 30px -5px rgba(212, 175, 55, 0.15);
}

.editorial-image {
    width: 100%;
    overflow: hidden;
    max-height: 300px;
}

.editorial-image .image-placeholder {
    width: 100%;
    height: 300px;
    transition: transform var(--transition-base);
}

.editorial-card:hover .editorial-image .image-placeholder {
    transform: scale(1.05);
}

.editorial-content {
    padding: var(--spacing-lg);
}

.editorial-tag {
    display: inline-block;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    color: var(--color-accent);
    margin-bottom: var(--spacing-sm);
}

.editorial-card h3 {
    margin-bottom: var(--spacing-md);
    font-size: 1.375rem;
}

.editorial-card p {
    margin-bottom: var(--spacing-md);
    line-height: 1.7;
}

.read-more {
    display: inline-block;
    color: var(--color-accent);
    font-weight: 600;
    transition: all var(--transition-fast);
    position: relative;
}

.read-more::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--color-accent);
    transition: width var(--transition-fast);
}

.read-more:hover::after {
    width: 100%;
}

/* ============================================================================
   Newsletter Section
   ============================================================================ */

.newsletter {
    background: linear-gradient(135deg, var(--color-accent-alt), var(--color-accent));
    color: var(--color-bg-primary);
}

.newsletter-content {
    text-align: center;
    max-width: 600px;
    margin: 0 auto;
}

.newsletter-content h2 {
    color: var(--color-bg-primary);
    margin-bottom: var(--spacing-md);
}

.newsletter-content p {
    color: rgba(10, 14, 39, 0.8);
    margin-bottom: var(--spacing-lg);
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-lg);
}

.newsletter-form input {
    flex: 1;
    padding: 0.75rem;
    background-color: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: var(--radius-md);
    color: var(--color-bg-primary);
    font-size: 1rem;
}

.newsletter-form input::placeholder {
    color: rgba(10, 14, 39, 0.6);
}

.newsletter-form input:focus {
    outline: none;
    background-color: rgba(255, 255, 255, 0.15);
    border-color: var(--color-bg-primary);
}

.newsletter-form button {
    padding: 0.75rem 2rem;
    background-color: var(--color-bg-primary);
    color: var(--color-accent);
    border: none;
    border-radius: var(--radius-md);
    font-weight: 600;
    cursor: pointer;
    transition: all var(--transition-base);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.newsletter-form button:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.3);
}

.newsletter-note {
    font-size: 0.875rem;
    color: rgba(10, 14, 39, 0.7);
}

/* ============================================================================
   Footer
   ============================================================================ */

.footer {
    background-color: var(--color-bg-secondary);
    border-top: 1px solid var(--color-border);
    padding: var(--spacing-2xl) 0;
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-xl);
    margin-bottom: var(--spacing-2xl);
    padding-bottom: var(--spacing-xl);
    border-bottom: 1px solid var(--color-border);
}

.footer-section h4 {
    margin-bottom: var(--spacing-md);
    color: var(--color-text-primary);
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: var(--spacing-sm);
}

.footer-section a {
    color: var(--color-text-secondary);
    font-size: 0.875rem;
}

.footer-section a:hover {
    color: var(--color-accent);
}

.social-links {
    display: flex;
    flex-wrap: wrap;
    gap: var(--spacing-sm);
}

.social-link {
    display: inline-block;
    color: var(--color-text-secondary);
    font-size: 0.875rem;
}

.social-link:hover {
    color: var(--color-accent);
}

