    .deals-grid {
        grid-template-columns: 1fr;
    }

    .deal-large {
        grid-column: span 1;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .cart-sidebar {
        width: 100%;
        max-width: 100%;
    }

